"""Weighted least squares: recovery, covariance, intervals, and the trap.

Every ``pytest.approx`` call passes an explicit ``abs=``.
"""

from __future__ import annotations

import math

import numpy as np
import pytest
from scipy import stats

from pointmodel import synthetic, terms, wls


class TestRecovery:
    """Coefficient recovery from residual sets with known truth."""

    def test_noiseless_full_sky_recovers_every_term(
        self, noiseless_full_sky: synthetic.ResidualSet
    ) -> None:
        # The truth was generated by the exact rotation model, so the residual
        # left after a first-order fit is the truncation of equation (16), not
        # zero. The total misalignment of the nominal coefficients is about
        # 174 arcsec, so the per-observation truncation is of order
        # (174 / 206265)^2 * 206265 = 0.147 arcsec and the recovery error is
        # bounded by a few times that after averaging over 160 observations.
        result = wls.fit(
            noiseless_full_sky.design, noiseless_full_sky.observed, sigma_arcsec_or_one()
        )
        error = np.abs(result.coefficients - noiseless_full_sky.coefficients)
        assert float(np.max(error)) < 0.5
        assert result.rank == terms.N_TERMS

    def test_linear_truth_recovers_exactly_to_rounding(self) -> None:
        residuals = synthetic.generate(
            "full_sky", 120, sigma_arcsec=0.0, seed=5, linear_truth=True
        )
        result = wls.fit(residuals.design, residuals.observed, 1.0)
        assert result.coefficients == pytest.approx(
            residuals.coefficients, rel=1e-9, abs=1e-9
        )

    def test_noisy_recovery_sits_inside_its_own_intervals(
        self, clean_full_sky: synthetic.ResidualSet
    ) -> None:
        result = wls.fit(
            clean_full_sky.design, clean_full_sky.observed, clean_full_sky.sigma_arcsec
        )
        inside = np.logical_and(
            result.confidence_intervals[:, 0] <= clean_full_sky.coefficients,
            clean_full_sky.coefficients <= result.confidence_intervals[:, 1],
        )
        # Nine 95 per cent intervals on one realisation: all nine covering is
        # the expected outcome and eight is unremarkable. Fewer than seven is
        # a signal. This is a declared criterion, not the seed.
        assert int(np.count_nonzero(inside)) >= 7

    def test_reduced_chi_square_is_near_one_on_a_well_specified_fit(
        self, clean_full_sky: synthetic.ResidualSet
    ) -> None:
        result = wls.fit(
            clean_full_sky.design, clean_full_sky.observed, clean_full_sky.sigma_arcsec
        )
        # 480 rows, 9 parameters: the reduced chi-square has standard
        # deviation sqrt(2/471) = 0.0652, so a four-sigma band is 0.26.
        spread = math.sqrt(2.0 / result.degrees_of_freedom)
        assert abs(result.reduced_chi_square - 1.0) < 4.0 * spread


class TestCovarianceAndIntervals:
    """Equation (20) and the interval multipliers."""

    def test_covariance_is_symmetric_positive_semidefinite(
        self, clean_full_sky: synthetic.ResidualSet
    ) -> None:
        result = wls.fit(clean_full_sky.design, clean_full_sky.observed, 2.0)
        assert result.covariance == pytest.approx(
            result.covariance.T, rel=1e-12, abs=1e-18
        )
        eigenvalues = np.linalg.eigvalsh(result.covariance)
        assert float(np.min(eigenvalues)) > -1e-12 * float(np.max(eigenvalues))

    def test_standard_errors_are_the_covariance_diagonal(
        self, clean_full_sky: synthetic.ResidualSet
    ) -> None:
        result = wls.fit(clean_full_sky.design, clean_full_sky.observed, 2.0)
        assert result.standard_errors == pytest.approx(
            np.sqrt(np.diag(result.covariance)), rel=1e-13, abs=0.0
        )

    def test_intervals_use_the_student_t_multiplier_when_scaled(
        self, clean_full_sky: synthetic.ResidualSet
    ) -> None:
        result = wls.fit(
            clean_full_sky.design, clean_full_sky.observed, 2.0, error_model="scaled"
        )
        expected = float(stats.t.ppf(0.975, result.degrees_of_freedom))
        assert result.interval_multiplier == pytest.approx(expected, rel=1e-13, abs=0.0)
        width = result.confidence_intervals[:, 1] - result.confidence_intervals[:, 0]
        assert width == pytest.approx(
            2.0 * expected * result.standard_errors, rel=1e-13, abs=0.0
        )

    def test_intervals_use_the_normal_multiplier_when_declared(
        self, clean_full_sky: synthetic.ResidualSet
    ) -> None:
        result = wls.fit(
            clean_full_sky.design, clean_full_sky.observed, 2.0, error_model="declared"
        )
        # Hand calculation: the two-sided 95 per cent normal quantile is
        # 1.959963984540054.
        assert result.interval_multiplier == pytest.approx(
            1.959963984540054, rel=1e-12, abs=0.0
        )

    def test_declared_error_model_ignores_the_residual_scale(
        self, clean_full_sky: synthetic.ResidualSet
    ) -> None:
        declared = wls.fit(
            clean_full_sky.design, clean_full_sky.observed, 2.0, error_model="declared"
        )
        scaled = wls.fit(
            clean_full_sky.design, clean_full_sky.observed, 2.0, error_model="scaled"
        )
        ratio = scaled.standard_errors / declared.standard_errors
        assert ratio == pytest.approx(
            np.full(terms.N_TERMS, math.sqrt(scaled.reduced_chi_square)),
            rel=1e-12,
            abs=0.0,
        )

    def test_a_wider_level_gives_a_wider_interval(
        self, clean_full_sky: synthetic.ResidualSet
    ) -> None:
        narrow = wls.fit(
            clean_full_sky.design, clean_full_sky.observed, 2.0, confidence_level=0.68
        )
        wide = wls.fit(
            clean_full_sky.design, clean_full_sky.observed, 2.0, confidence_level=0.99
        )
        assert wide.interval_multiplier > narrow.interval_multiplier


class TestWeighting:
    """What the weights actually do."""

    def test_uniform_sigma_scales_the_covariance_quadratically(
        self, clean_full_sky: synthetic.ResidualSet
    ) -> None:
        # With error_model="declared" and uniform sigma, doubling sigma must
        # double every standard error and leave the coefficients unchanged.
        one = wls.fit(
            clean_full_sky.design, clean_full_sky.observed, 1.0, error_model="declared"
        )
        two = wls.fit(
            clean_full_sky.design, clean_full_sky.observed, 2.0, error_model="declared"
        )
        assert two.coefficients == pytest.approx(one.coefficients, rel=1e-11, abs=1e-11)
        assert two.standard_errors == pytest.approx(
            2.0 * one.standard_errors, rel=1e-12, abs=0.0
        )

    def test_a_downweighted_row_moves_the_fit_toward_the_rest(
        self, clean_full_sky: synthetic.ResidualSet
    ) -> None:
        corrupted = clean_full_sky.observed.copy()
        corrupted[0] += 500.0
        uniform = wls.fit(clean_full_sky.design, corrupted, 2.0)
        sigma = np.full(corrupted.size, 2.0)
        sigma[0] = 1e4
        downweighted = wls.fit(clean_full_sky.design, corrupted, sigma)
        clean = wls.fit(clean_full_sky.design, clean_full_sky.observed, 2.0)
        assert float(
            np.linalg.norm(downweighted.coefficients - clean.coefficients)
        ) < float(np.linalg.norm(uniform.coefficients - clean.coefficients))


class TestVarianceInflation:
    """Equation (21)."""

    def test_an_orthogonal_design_has_unit_inflation(self) -> None:
        # Construct an orthogonal design directly. Column k is the Rademacher
        # function (-1) ** (bit k of the row index). Over all 2^9 = 512 row
        # indices any two distinct such columns are orthogonal exactly, in
        # integer arithmetic, so every VIF is exactly 1 in exact arithmetic and
        # 1 to rounding here.
        rows = 512
        columns = []
        for index in range(terms.N_TERMS):
            pattern = np.ones(rows)
            pattern[(np.arange(rows) >> index) % 2 == 1] = -1.0
            columns.append(pattern)
        design = np.stack(columns, axis=1)
        assert np.allclose(design.T @ design, np.diag(np.diag(design.T @ design)), atol=1e-9)
        result = wls.fit(design, np.zeros(rows), 1.0, error_model="declared")
        assert result.vif == pytest.approx(np.ones(terms.N_TERMS), rel=1e-10, abs=0.0)

    def test_inflation_is_large_on_a_restricted_geometry(
        self, narrow_band: synthetic.ResidualSet, clean_full_sky: synthetic.ResidualSet
    ) -> None:
        restricted = wls.fit(narrow_band.design, narrow_band.observed, 2.0)
        good = wls.fit(clean_full_sky.design, clean_full_sky.observed, 2.0)
        assert float(np.max(restricted.vif)) > 1e4 * float(np.max(good.vif))

    def test_inflation_is_scale_invariant(
        self, clean_full_sky: synthetic.ResidualSet
    ) -> None:
        # Rescaling a column rescales its coefficient and its standard error
        # together, so the variance inflation factor must not move.
        scaled_design = clean_full_sky.design.copy()
        scaled_design[:, terms.TERM_INDEX["RF"]] *= 1000.0
        base = wls.fit(clean_full_sky.design, clean_full_sky.observed, 2.0)
        rescaled = wls.fit(scaled_design, clean_full_sky.observed, 2.0)
        assert rescaled.vif == pytest.approx(base.vif, rel=1e-6, abs=0.0)


class TestNormalEquationTrap:
    """The reason :func:`wls.fit` does not use equations (19) and (20)."""

    def test_agrees_with_the_svd_on_a_good_geometry(
        self, clean_full_sky: synthetic.ResidualSet
    ) -> None:
        svd = wls.fit(clean_full_sky.design, clean_full_sky.observed, 2.0)
        normal = wls.normal_equation_fit(
            clean_full_sky.design, clean_full_sky.observed, 2.0
        )
        assert normal.coefficients == pytest.approx(svd.coefficients, rel=1e-8, abs=1e-9)
        assert normal.standard_errors == pytest.approx(
            svd.standard_errors, rel=1e-8, abs=0.0
        )

    def test_reports_a_full_rank_on_a_rank_deficient_geometry(
        self, single_azimuth: synthetic.ResidualSet
    ) -> None:
        normal = wls.normal_equation_fit(
            single_azimuth.design, single_azimuth.observed, 2.0
        )
        svd = wls.fit(single_azimuth.design, single_azimuth.observed, 2.0)
        assert normal.rank == terms.N_TERMS
        assert svd.rank < terms.N_TERMS

    def test_its_formal_errors_are_enormous_where_the_scatter_is_not(
        self, single_azimuth: synthetic.ResidualSet
    ) -> None:
        # The normal matrix squares a condition number already at 1e15, so its
        # inverse is numerical noise. The formal standard errors it reports on
        # the degenerate terms exceed a thousand arcseconds while the actual
        # scatter over noise realisations, measured in
        # validation/validate_identifiability.py, is tens of arcseconds.
        normal = wls.normal_equation_fit(
            single_azimuth.design, single_azimuth.observed, 2.0
        )
        degenerate = [terms.TERM_INDEX[name] for name in ("AN", "AW", "NPAE", "IE")]
        assert float(np.min(normal.standard_errors[degenerate])) > 1e3


class TestInputValidation:
    """Every rejection path."""

    def test_rejects_wrong_column_count(self) -> None:
        with pytest.raises(ValueError, match="must have 9 columns"):
            wls.fit(np.zeros((20, 5)), np.zeros(20), 1.0)

    def test_rejects_mismatched_observation_length(self) -> None:
        with pytest.raises(ValueError, match="observed must be 1-D"):
            wls.fit(np.zeros((20, terms.N_TERMS)), np.zeros(19), 1.0)

    def test_rejects_too_few_rows(self) -> None:
        with pytest.raises(ValueError, match="cannot constrain"):
            wls.fit(np.zeros((4, terms.N_TERMS)), np.zeros(4), 1.0)

    def test_rejects_non_positive_sigma(self) -> None:
        with pytest.raises(ValueError, match="strictly positive"):
            wls.fit(np.ones((20, terms.N_TERMS)), np.zeros(20), 0.0)

    def test_rejects_non_finite_entries(self) -> None:
        design = np.ones((20, terms.N_TERMS))
        design[0, 0] = np.nan
        with pytest.raises(ValueError, match="non-finite"):
            wls.fit(design, np.zeros(20), 1.0)

    def test_rejects_an_unknown_error_model(self) -> None:
        with pytest.raises(ValueError, match="error_model must be"):
            wls.fit(np.ones((20, terms.N_TERMS)), np.zeros(20), 1.0, error_model="guess")

    def test_rejects_an_out_of_range_confidence_level(self) -> None:
        with pytest.raises(ValueError, match="strictly in"):
            wls.fit(np.ones((20, terms.N_TERMS)), np.zeros(20), 1.0, confidence_level=1.0)

    def test_rejects_an_identically_zero_column(self) -> None:
        design = np.ones((20, terms.N_TERMS))
        design[:, terms.TERM_INDEX["RF"]] = 0.0
        with pytest.raises(ValueError, match="identically zero"):
            wls.fit(design, np.zeros(20), 1.0)


def sigma_arcsec_or_one() -> float:
    """1.0, for a noiseless set where the declared sigma is a pure weighting."""
    return 1.0
